const now = new Date();
const end = new Date(now);
const start = new Date(now);
start.setDate(start.getDate() - 7);
return [{ json: {
  source: 'demo_data',
  reportingPeriod: { start: start.toISOString().slice(0,10), end: end.toISOString().slice(0,10) },
  revenue: 125000, previousRevenue: 110000,
  completedOrders: 840, previousOrders: 790,
  qualifiedSessions: 12000, previousQualifiedSessions: 10800,
  pipelineValue: 480000, previousPipelineValue: 450000,
  dataFreshness: now.toISOString()
} }];

const d = $json;
const pct = (a,b) => b === 0 ? null : Number(((a-b)/Math.abs(b)*100).toFixed(2));
const conversionRate = d.qualifiedSessions ? Number((d.completedOrders/d.qualifiedSessions*100).toFixed(2)) : null;
const previousConversionRate = d.previousQualifiedSessions ? Number((d.previousOrders/d.previousQualifiedSessions*100).toFixed(2)) : null;
return [{ json: { ...d, conversionRate, previousConversionRate, changes: { revenue: pct(d.revenue,d.previousRevenue), completedOrders: pct(d.completedOrders,d.previousOrders), conversionRate: pct(conversionRate,previousConversionRate), pipelineValue: pct(d.pipelineValue,d.previousPipelineValue) } } }];

const d = $json;
const required = ['revenue','previousRevenue','completedOrders','previousOrders','qualifiedSessions','previousQualifiedSessions','pipelineValue','previousPipelineValue'];
const errors = required.filter(k => d[k] === undefined || d[k] === null);
const warnings = Object.entries(d.changes || {}).filter(([,v]) => v !== null && Math.abs(v) > 30).map(([k,v]) => `${k} changed by ${v}%`);
return [{ json: { ...d, validation: { passed: errors.length === 0, errors, warnings } } }];

const d = $json;
const f = (v) => v === null || v === undefined ? 'N/A' : `${v}%`;
const row = (label,current,previous,change) => `| ${label} | ${current} | ${previous} | ${f(change)} |`;
const report = `# Weekly Business Performance Report

**Period:** ${d.reportingPeriod.start} to ${d.reportingPeriod.end}
**Generated:** ${new Date().toISOString()}
**Validation:** ${d.validation.passed ? 'PASSED' : 'FAILED'}

## Executive summary
Revenue was ${d.revenue} compared with ${d.previousRevenue} in the previous period, a change of ${f(d.changes.revenue)}. Completed orders changed by ${f(d.changes.completedOrders)}.

## KPI performance
| Metric | Current | Previous | Change |
|---|---:|---:|---:|
${row('Revenue',d.revenue,d.previousRevenue,d.changes.revenue)}
${row('Completed orders',d.completedOrders,d.previousOrders,d.changes.completedOrders)}
${row('Conversion rate',d.conversionRate+'%',d.previousConversionRate+'%',d.changes.conversionRate)}
${row('Pipeline value',d.pipelineValue,d.previousPipelineValue,d.changes.pipelineValue)}

## Anomalies and warnings
${d.validation.warnings.length ? d.validation.warnings.map(x => '- '+x).join('\n') : '- No threshold anomalies detected.'}

## Methodology
Metrics were calculated from the workflow input. Replace the Demo Data node with a database, API, spreadsheet, or other approved source before production use.

## Sources
- [demo_data] Demo Data node in this workflow.
`;
return [{ json: { ...d, reportMarkdown: report, reportStatus: d.validation.passed ? 'ready' : 'blocked' } }];
